<?php
function teachingCalendarReady():bool{try{q('SELECT id FROM teaching_calendars LIMIT 1');return true;}catch(PDOException $e){return false;}}
function manualClassRow(array $p):array{
 attRequire(teachingCalendarReady(),'Run the database migration first.');
 $term=one('SELECT * FROM teaching_calendars WHERE id=? AND active=1',[(int)($p['calendar_id']??0)]);$time=one('SELECT * FROM teaching_time_slots WHERE id=? AND active=1',[(int)($p['time_slot_id']??0)]);
 attRequire($term&&$time,'Select an Admin-configured academic calendar and class timing.');
 $r=$p['row']??[];attRequire(in_array($r['Year']??'',['I','II','III','IV'],true),'Select Year I, II, III or IV.');attRequire(($r['Semester']??'')===$term['semester'],'Semester must match the selected academic calendar.');
 $primary=[['department'=>$r['Department']??'','programme'=>$r['Programme']??'','year_level'=>$r['Year']??'','section'=>$r['Section']??'']];$r['Participant Groups']=array_merge($primary,array_values($p['groups']??[]));
 $date=trim($r['Class Date']??'');attRequire(($p['schedule_mode']??'')!=='specific'||$date!=='','Select the actual date for a specific-date research class.');attRequire(($p['schedule_mode']??'')!=='weekly'||$date==='','Leave Class Date blank for weekly sessions.');attRequire(!$date||($date>=$term['valid_from']&&$date<=$term['valid_until']),'Class date must fall within the Admin-configured calendar.');
 return array_merge($r,['Academic Year'=>$term['academic_year'],'Valid From'=>$term['valid_from'],'Valid Until'=>$term['valid_until'],'Start Time'=>$time['start_time'],'End Time'=>$time['end_time']]);
}
function saveTeachingCalendar(array $u,array $p):void{
 attRequire($u['role']==='admin');$year=required($p,'academic_year');$semester=required($p,'semester');$from=required($p,'valid_from');$until=required($p,'valid_until');
 attRequire(mb_strlen($year)<=40&&in_array($semester,['I','II'],true)&&dateValid($from)&&dateValid($until)&&$until>=$from&&(strtotime($until)-strtotime($from))<=366*86400,'Check academic year, semester and calendar dates (maximum one year).');
 attRequire(!one('SELECT id FROM teaching_calendars WHERE academic_year=? AND semester=? AND valid_from=? AND valid_until=? AND active=1',[$year,$semester,$from,$until]),'This calendar already exists.');
 q('INSERT INTO teaching_calendars(academic_year,semester,valid_from,valid_until) VALUES(?,?,?,?)',[$year,$semester,$from,$until]);attAudit((int)$u['id'],'Teaching calendar added',(int)db()->lastInsertId());
}
function saveTeachingTime(array $u,array $p):void{
 attRequire($u['role']==='admin');$a=required($p,'start_time');$b=required($p,'end_time');attRequire(timeValid($a)&&timeValid($b)&&$b>$a,'Use a valid start and end time.');attRequire(!one('SELECT id FROM teaching_time_slots WHERE start_time=? AND end_time=? AND active=1',[$a,$b]),'This timing already exists.');q('INSERT INTO teaching_time_slots(start_time,end_time) VALUES(?,?)',[$a,$b]);attAudit((int)$u['id'],'Class timing added',(int)db()->lastInsertId());
}
function teachingFileRows(string $path,string $name):array{
 $rows=workbookRows($path,$name);$h=$rows[0]??[];
 foreach(['Academic Year','Year','Semester','Valid From','Valid Until']as $key)attRequire(in_array($key,$h,true),'Use the new row template: missing '.$key.'. All details must be in the file.');
 foreach(array_slice($rows,1)as $i=>$r){if(!array_filter($r))continue;$semester=trim($r[array_search('Semester',$h)]??'');attRequire(in_array($semester,['I','II'],true),'Row '.($i+2).': Semester must be I or II.');$classDate=trim($r[array_search('Class Date',$h)]??'');if(in_array('Class Date',$h,true)&&$classDate!=='')attRequire($classDate>=($r[array_search('Valid From',$h)]??'')&&$classDate<=($r[array_search('Valid Until',$h)]??''),'Row '.($i+2).': Class Date is outside the valid dates.');foreach(['Valid From','Valid Until']as $key)attRequire(trim($r[array_search($key,$h)]??'')!=='','Row '.($i+2).': '.$key.' is required in the file.');}
 return $rows;
}
function teachingRowTemplate(bool $csv=false):never{
 $headers=attHeaders();if($csv){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="teaching-timetable-template.csv"');$f=fopen('php://output','w');fputcsv($f,$headers);fclose($f);exit;}
 $book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Timetable');$sheet->fromArray([$headers]);$sheet->freezePane('A2');
 foreach(range(1,count($headers))as $c)$sheet->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($c))->setWidth(24);
 $sheet->getStyle('A1:Q1')->getFont()->setBold(true);$sheet->getStyle('A1:Q1')->getFill()->setFillType('solid')->getStartColor()->setARGB('FFDCEAF9');
 foreach(['B'=>'"I,II"','E'=>'"I,II,III,IV"','K'=>'"Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday"']as $col=>$formula){$v=$sheet->getCell($col.'2')->getDataValidation();$v->setType('list')->setAllowBlank(false)->setShowDropDown(true)->setShowErrorMessage(true)->setErrorStyle('stop')->setFormula1($formula);$v->setSqref($col.'2:'.$col.'5001');}
 $guide=$book->createSheet();$guide->setTitle('Instructions');$guide->fromArray([['One row = one participating group in a session.'],['For combined classes repeat the same Combined Session ID for all groups.'],['Tutor, module, date/day, times, room and term must match for that ID.'],['Student Count is the optional TOTAL across the combined session.'],['Use a different ID for each separate session, even for the same module.'],['The same tutor/module may appear on Monday, Wednesday and any other day.'],['Leave Class Date blank for weekly repetition between Valid From and Valid Until.'],['For a one-off session, supply Class Date matching Day and within the term dates.'],['Copy the Admin calendar and timing values from Settings below into each Timetable row.'],['Use Year I-IV, Semester I-II, dates YYYY-MM-DD and times HH:MM.'],['Use active attendance-enabled Tutor Email and an existing classroom code.'],['Department means the department receiving the class, not necessarily the tutor home department.'],['Upload only after entering your real data in the first Timetable sheet.'],['EXAMPLE ONLY: same tutor and module on separate weekdays'],['Tutor Email','Subject Code','Day','Start Time','End Time'],['tutor@example.invalid','MODULE-A','Monday','09:00','10:00'],['tutor@example.invalid','MODULE-A','Wednesday','09:00','10:00'],['tutor@example.invalid','MODULE-A','Friday','10:15','11:15']]);$guide->getColumnDimension('A')->setWidth(95);foreach(['B','C','D','E']as $col)$guide->getColumnDimension($col)->setWidth(24);
 $settings=$book->createSheet();$settings->setTitle('Settings');$rows=[['Academic Year','Semester','Valid From','Valid Until']];if(teachingCalendarReady())foreach(all('SELECT * FROM teaching_calendars WHERE active=1 ORDER BY valid_from DESC')as $t)$rows[]=[$t['academic_year'],$t['semester'],$t['valid_from'],$t['valid_until']];$rows[]=[];$rows[]=['Start Time','End Time'];if(teachingCalendarReady())foreach(all('SELECT * FROM teaching_time_slots WHERE active=1 ORDER BY start_time')as $t)$rows[]=[$t['start_time'],$t['end_time']];$rows[]=[];$rows[]=['Department'];foreach(departments()as $d)$rows[]=[$d];$rows[]=[];$rows[]=['Programme'];foreach(programmes()as $d)$rows[]=[$d];$settings->fromArray($rows);foreach(['A','B','C','D']as $col)$settings->getColumnDimension($col)->setWidth(45);
 $book->setActiveSheetIndex(0);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="teaching-timetable-template.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;
}
